225	    /**
226	     * Whether more than 80 owners had already been created today at the time this owner
227	     * was created, indicating an unusually high signup volume.
228	     *
229	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
230	     *         {@code false} (never {@code null})
231	     */
232	    public Boolean getBulkSignupWarning() {
233	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
234	    }
235	
236	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
237	        this.bulkSignupWarning = bulkSignupWarning;
238	    }
239	
240	    /**
241	     * The number of owners in this owner's household (owners sharing the same
242	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
243	     * membership tier.
244	     *
245	     * @return the household member count, or {@code null} if it has not been assigned
246	     */
247	    public Integer getHouseholdSize() {
248	        return this.householdSize;
249	    }
250	
251	    public void setHouseholdSize(Integer householdSize) {
252	        this.householdSize = householdSize;
253	    }
254	
255	    /**
256	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
257	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
258	     *
259	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
260	     *         {@code false} (never {@code null})
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate != null && this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner may duplicate (same last name and postcode,
272	     * different telephone), or {@code null} when this owner is not a possible duplicate.
273	     *
274	     * @return the matching owner id, or {@code null}
275	     */
276	    public Integer getPossibleDuplicateOf() {
277	        return this.possibleDuplicateOf;
278	    }
279	
280	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
281	        this.possibleDuplicateOf = possibleDuplicateOf;
282	    }
283	
284	    /**
285	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
286	     *
287	     * @return the formatted display name
288	     */
289	    public String getDisplayName() {
290	        return this.getLastName() + ", " + this.getFirstName();
291	    }
292	
293	    /**
294	     * The owner's initials: the upper-cased first letters of the first and last
295	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
296	     *
297	     * @return the formatted initials
298	     */
299	    public String getInitials() {
300	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
301	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
302	    }
303	
304	    /**
305	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
306	     * {@code YY} is the last two digits of the registration date's year (e.g.
307	     * {@code "NSW-1A2B3C4D-M26"}).
308	     *
309	     * @return the formatted membership number, or {@code null} if the customer code or
310	     *         registration date has not been assigned
311	     */
312	    public String getMembershipNumber() {
313	        if (this.customerCode == null || this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
317	    }
318	
319	    /**
320	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
321	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
322	     * (non-digit characters are ignored).
323	     *
324	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
325	     */
326	    public Integer getCheckDigit() {
327	        if (this.customerCode == null) {
328	            return null;
329	        }
330	        int sum = 0;
331	        boolean dbl = true;
332	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
333	            char c = this.customerCode.charAt(i);
334	            if (c < '0' || c > '9') {
335	                continue;
336	            }
337	            int d = c - '0';
338	            if (dbl) {
339	                d *= 2;
340	                if (d > 9) {
341	                    d -= 9;
342	                }
343	            }
344	            sum += d;
345	            dbl = !dbl;
346	        }
347	        return (10 - (sum % 10)) % 10;
348	    }
349	
350	    /**
351	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
352	     * they carry an email address, {@code 1} when they have no namesakes
353	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
354	     * members ({@code householdSize}), and {@code 3} for tenure of more than {@code 365}
355	     * days (measured from the {@code registrationDate}). Because a newly created owner has
356	     * zero tenure, a new owner can score at most {@code 5} points.
357	     *
358	     * @return the membership points
359	     */
360	    public Integer getMembershipPoints() {
361	        int points = 0;
362	        boolean hasEmail = this.email != null && !this.email.isBlank();
363	        if (hasEmail) {
364	            points += 2;
365	        }
366	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
367	        if (noNamesakes) {
368	            points += 1;
369	        }
370	        if (this.householdSize != null && this.householdSize >= 3) {
371	            points += 2;
372	        }
373	        if (this.registrationDate != null
374	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
375	            points += 3;
376	        }
377	        return points;
378	    }
379	
380	    /**
381	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
382	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
383	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
384	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
385	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
386	     * is reserved for owners whose tenure exceeds {@code 365} days.
387	     *
388	     * @return the membership level
389	     */
390	    public Integer getMembershipLevel() {
391	        int points = getMembershipPoints();
392	        if (points >= 6) {
393	            return 4;
394	        }
395	        if (points >= 4) {
396	            return 3;
397	        }
398	        if (points >= 2) {
399	            return 2;
400	        }
401	        return 1;
402	    }
403	
404	    /**
405	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
406	     * email address, otherwise {@code "PHONE"}.
407	     *
408	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
409	     */
410	    public String getContactPreference() {
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        return hasEmail ? "EMAIL" : "PHONE";
413	    }
414	
415	    /**
416	     * The owner's identity key: the single derived value used for duplicate detection, formed as
417	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
418	     * email are the already-normalized stored values and a {@code null} email or household id is
419	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
420	     * are equal; because the telephone is part of the key, household members with different
421	     * telephones have different identity keys.
422	     *
423	     * @return the derived identity key
424	     */
425	    public String getIdentityKey() {
426	        String telephonePart = this.telephone == null ? "" : this.telephone;
427	        String emailPart = this.email == null ? "" : this.email;
428	        String householdPart = this.householdId == null ? "" : this.householdId;
429	        return telephonePart + "|" + emailPart + "|" + householdPart;
430	    }
431	
432	    /**
433	     * City -> canonical region, the fixed ground truth for deriving locality.
434	     */
435	    private static final Map<String, String> CITY_REGION = Map.of(
436	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
437	
438	    /**
439	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
440	     * deriving locality from the postcode ahead of the city.
441	     */
442	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
443	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
444	
445	    /**
446	     * The owner's locality: the canonical region resolved by the postcode range first
447	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
448	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
449	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
450	     * when the city is not in the table either. The postcode takes precedence so cities that share a
451	     * name are disambiguated by their postcode's region.
452	     *
453	     * @return the canonical region string, or {@code "UNKNOWN"}
454	     */
455	    public String getLocality() {
456	        String byPostcode = regionForPostcode(this.postcode);
457	        if (byPostcode != null) {
458	            return byPostcode;
459	        }
460	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
461	    }
462	
463	    /**
464	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
465	     * absent, not a 4-digit number, or in no known range.
466	     *
467	     * @param postcode the owner's postcode (may be {@code null})
468	     * @return the matching region, or {@code null}
469	     */
470	    private static String regionForPostcode(String postcode) {
471	        if (postcode == null || !postcode.matches("\\d{4}")) {
472	            return null;
473	        }
474	        int value = Integer.parseInt(postcode);
475	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
476	            int[] range = entry.getValue();
477	            if (value >= range[0] && value <= range[1]) {
478	                return entry.getKey();
479	            }
480	        }
481	        return null;
482	    }
483	
484	    protected Set<Pet> getPetsInternal() {
485	        if (this.pets == null) {
486	            this.pets = new HashSet<>();
487	        }
488	        return this.pets;
489	    }
490	
491	    protected void setPetsInternal(Set<Pet> pets) {
492	        this.pets = pets;
493	    }
494	
495	    public List<Pet> getPets() {
496	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
497	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
498	        return Collections.unmodifiableList(sortedPets);
499	    }
500	
501	    public void setPets(List<Pet> pets) {
502	        this.pets = new HashSet<>(pets);
503	    }
504	
505	    public void addPet(Pet pet) {
506	        getPetsInternal().add(pet);
507	        pet.setOwner(this);
508	    }
509	
510	    /**
511	     * Return the Pet with the given name, or null if none found for this Owner.
512	     *
513	     * @param name to test
514	     * @return true if pet name is already in use
515	     */
516	    public Pet getPet(String name) {
517	        return getPet(name, false);
518	    }
519	
520	    /**
521	     * Return the Pet with the given name, or null if none found for this Owner.
522	     *
523	     * @param name to test
524	     * @return true if pet name is already in use
525	     */
526	    public Pet getPet(String name, boolean ignoreNew) {
527	        name = name.toLowerCase();
528	        for (Pet pet : getPetsInternal()) {
529	            if (!ignoreNew || !pet.isNew()) {
530	                String compName = pet.getName();
531	                compName = compName.toLowerCase();
532	                if (compName.equals(name)) {
533	                    return pet;
534	                }
535	            }
536	        }
537	        return null;
538	    }
539	
540	    public Pet getPet(Integer petId) {
541	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
542	    }
543	
544	    @Override
545	    public String toString() {
546	        return new ToStringCreator(this)
547	
548	            .append("id", this.getId())
549	            .append("new", this.isNew())
550	            .append("lastName", this.getLastName())
551	            .append("firstName", this.getFirstName())
552	            .append("address", this.address)
553	            .append("city", this.city)
554	            .append("telephone", this.telephone)
555	            .append("email", this.email)
556	            .toString();
557	    }
558	}
